import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
  Card,
  CardContent,
  CardMedia,
  Chip,
} from '@mui/material';
import { Refresh, CloudDownload, Error } from '@mui/icons-material';

const Awards = () => {
  const [galleryData, setGalleryData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});
  const [debugInfo, setDebugInfo] = useState('');

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxHUCq3ypaIOv1yAiGQFxa_4FxoFJCnH7ZGGsxG9h_D66LqERLhOVtdNGDbSznM0uY31g/exec';

  const fetchGalleryData = async (isRetry = false) => {
    if (!isRetry) setLoading(true);
    setError(null);
    setDebugInfo('Fetching data...');
    
    try {
      console.log('=== FETCHING GALLERY DATA ===');
      console.log('URL:', SCRIPT_URL);
      
      const timestamp = Date.now();
      const fetchUrl = `${SCRIPT_URL}?t=${timestamp}`;
      console.log('Fetch URL:', fetchUrl);

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 15000);

      const response = await fetch(fetchUrl, {
        signal: controller.signal,
        mode: 'cors',
        headers: {
          'Content-Type': 'application/json',
        }
      });

      clearTimeout(timeoutId);
      
      console.log('Response status:', response.status);
      console.log('Response ok:', response.ok);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const textResponse = await response.text();
      console.log('Raw response text:', textResponse);

      let result;
      try {
        result = JSON.parse(textResponse);
      } catch (parseError) {
        console.error('JSON parse error:', parseError);
        throw new Error('Invalid JSON response from server');
      }

      console.log('Parsed result:', result);
      setDebugInfo(`Response received: ${JSON.stringify(result).substring(0, 200)}...`);

      // Handle different response structures
      let data = [];
      
      if (result.success === true && Array.isArray(result.data)) {
        data = result.data;
        console.log('Data found in result.data:', data.length, 'items');
      } else if (Array.isArray(result)) {
        data = result;
        console.log('Direct array response:', data.length, 'items');
      } else if (result.data && Array.isArray(result.data)) {
        data = result.data;
        console.log('Data found in nested data property:', data.length, 'items');
      } else {
        console.warn('Unexpected response structure:', result);
        setDebugInfo('Unexpected response structure: ' + JSON.stringify(result));
      }

      if (data.length > 0) {
        const transformedData = data.map((item, index) => {
          // Handle various field name possibilities
          const imageNo = item.imageNo || item['Image No'] || item['imageNo'] || index + 1;
          const fileName = item.fileName || item['File Name'] || item['fileName'] || `Certificate ${imageNo}`;
          const rawImageUrl = item.imageUrl || item['Image URL'] || item['imageUrl'] || '';
          const description = item.description || item.Description || '';

          console.log(`Processing item ${index}:`, { imageNo, fileName, rawImageUrl });

          return {
            imageNo,
            fileName,
            imageUrl: convertToDirectUrl(rawImageUrl),
            description,
            rawData: item // Keep original for debugging
          };
        });

        console.log('Transformed data:', transformedData);
        setGalleryData(transformedData);

        const initialLoadingStates = {};
        transformedData.forEach((_, index) => {
          initialLoadingStates[index] = true;
        });
        setImageLoadingStates(initialLoadingStates);
        
        setDebugInfo(`Successfully loaded ${transformedData.length} items`);
      } else {
        setGalleryData([]);
        setDebugInfo('No data items found in response');
        console.warn('No data items found in response');
      }

    } catch (err) {
      console.error('=== FETCH ERROR ===', err);
      
      let errorMessage = 'Failed to load certificates: ';
      let debugMessage = `Error: ${err.message}`;

      if (err.name === 'AbortError') {
        errorMessage += 'Request timed out (15 seconds). The server might be slow or unavailable.';
        debugMessage += ' - Request timeout';
      } else if (err.message.includes('HTTP error') || err.message.includes('HTTP')) {
        errorMessage += `Server returned an error: ${err.message}`;
        debugMessage += ' - HTTP error';
      } else if (err.message.includes('Failed to fetch') || err.message.includes('Network')) {
        errorMessage += 'Network error. Please check your internet connection.';
        debugMessage += ' - Network error';
      } else if (err.message.includes('JSON')) {
        errorMessage += 'Server returned invalid data.';
        debugMessage += ' - JSON parse error';
      } else {
        errorMessage += err.message;
      }

      setError(errorMessage);
      setDebugInfo(debugMessage);
    } finally {
      setLoading(false);
    }
  };

  const convertToDirectUrl = (url) => {
    if (!url) {
      console.warn('convertToDirectUrl: Empty URL provided');
      return '';
    }

    console.log('Converting URL:', url);
    
    let fileId = '';
    const patterns = [
      /\/file\/d\/([^\/]+)/,
      /uc\?id=([^&]+)/,
      /open\?id=([^&]+)/,
      /id=([^&]+)/,
      /([-\w]{25,})/
    ];

    for (const pattern of patterns) {
      const match = url.match(pattern);
      if (match && match[1]) {
        fileId = match[1];
        break;
      }
    }

    if (fileId) {
      const directUrl = `https://drive.google.com/uc?id=${fileId}&export=view`;
      console.log('Converted to direct URL:', directUrl);
      return directUrl;
    }

    console.warn('Could not extract fileId from URL:', url);
    return url;
  };

  const getThumbnailUrl = (url) => {
    if (!url) return '';

    const fileId = url.split('uc?id=')[1]?.split('&')[0];
    if (fileId) {
      return `https://drive.google.com/thumbnail?id=${fileId}&sz=w400`;
    }
    return url;
  };

  const handleImageLoad = (index) => {
    setImageLoadingStates(prev => ({ ...prev, [index]: false }));
  };

  const handleImageError = (index, url) => {
    console.error(`Image ${index} failed to load:`, url);
    setImageLoadingStates(prev => ({ ...prev, [index]: false }));
  };

  const getColumns = () => {
    if (isMobile) return 1;
    if (isTablet) return 2;
    return 3;
  };

  useEffect(() => {
    fetchGalleryData();
  }, []);

  const testDirectAccess = () => {
    window.open(SCRIPT_URL, '_blank');
  };

  const viewDebugInfo = () => {
    console.log('=== DEBUG INFO ===');
    console.log('Gallery Data:', galleryData);
    console.log('Loading States:', imageLoadingStates);
    console.log('Error:', error);
    console.log('Debug Info:', debugInfo);
    
    alert(`Debug Info:\n${debugInfo}\n\nCheck console for full details.`);
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="300px" flexDirection="column" gap={2}>
        <CircularProgress size={60} />
        <Typography variant="h6">Loading certificates...</Typography>
        <Typography variant="body2" color="text.secondary">
          This may take a few moments
        </Typography>
        <Button variant="outlined" onClick={() => setDebugInfo('Loading in progress...')}>
          Show Debug Info
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      
      {/* Header */}
      <Box textAlign="center" mb={4}>
        <Typography variant="h4" component="h1" gutterBottom sx={{ fontWeight: 'bold', color: 'primary.main' }}>
          BT Certificates
        </Typography>
        
        <Box display="flex" justifyContent="center" gap={1} alignItems="center" flexWrap="wrap" mb={2}>
          <Chip 
            icon={<CloudDownload />} 
            label={`${galleryData.length} certificates`} 
            variant="outlined" 
            color="primary" 
          />
          <Button variant="outlined" size="small" onClick={viewDebugInfo}>
            Debug Info
          </Button>
          <Button variant="outlined" size="small" onClick={testDirectAccess}>
            Test API
          </Button>
        </Box>
      </Box>

      {error && (
        <Box mb={3}>
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
          <Box display="flex" gap={2} flexDirection={{ xs: 'column', sm: 'row' }} justifyContent="center">
            <Button variant="contained" startIcon={<Refresh />} onClick={() => fetchGalleryData(true)}>
              Retry
            </Button>
            <Button variant="outlined" onClick={testDirectAccess}>
              Test API Directly
            </Button>
            <Button variant="outlined" onClick={viewDebugInfo}>
              View Details
            </Button>
          </Box>
        </Box>
      )}

      {galleryData.length === 0 && !error ? (
        <Box textAlign="center" p={4}>
          <Error sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
          <Typography variant="h6" gutterBottom>
            No certificates found
          </Typography>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            The gallery appears to be empty or there might be a configuration issue.
          </Typography>
          <Button variant="contained" startIcon={<Refresh />} onClick={fetchGalleryData} sx={{ mt: 2 }}>
            Check Again
          </Button>
        </Box>
      ) : (
        <>
          <Box sx={{
            display: 'grid',
            gridTemplateColumns: {
              xs: 'repeat(1, 1fr)',
              sm: `repeat(${getColumns()}, 1fr)`,
              md: `repeat(${getColumns()}, 1fr)`
            },
            gap: 3
          }}>
            {galleryData.map((item, idx) => (
              <Card key={idx} sx={{ transition: 'all 0.3s ease', '&:hover': { transform: 'translateY(-4px)' } }}>
                <Box sx={{ position: 'relative', minHeight: 200 }}>
                  {imageLoadingStates[idx] && (
                    <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <CircularProgress />
                    </Box>
                  )}
                  <CardMedia
                    component="img"
                    image={getThumbnailUrl(item.imageUrl)}
                    alt={item.fileName}
                    sx={{ 
                      height: 200, 
                      objectFit: 'contain',
                      opacity: imageLoadingStates[idx] ? 0 : 1 
                    }}
                    onLoad={() => handleImageLoad(idx)}
                    onError={() => handleImageError(idx, item.imageUrl)}
                  />
                </Box>
                <CardContent>
                  <Typography variant="caption" color="text.secondary">Cert {item.imageNo}</Typography>
                  <Typography variant="h6" sx={{ fontSize: '1rem', mb: 1 }}>{item.fileName}</Typography>
                  {item.description && <Typography variant="body2" color="text.secondary">{item.description}</Typography>}
                </CardContent>
              </Card>
            ))}
          </Box>

          <Box textAlign="center" mt={4}>
            <Button variant="outlined" startIcon={<Refresh />} onClick={fetchGalleryData}>
              Refresh Certificates
            </Button>
          </Box>
        </>
      )}
    </Box>
  );
};

export default Awards;
